async function GET() {
  try {
    // Check if metadata file exists
    if (!existsSync(METADATA_FILE)) {
      return NextResponse.json({ files: [] });
    }

    // Read metadata file
    const metadataContent = await readFile(METADATA_FILE, 'utf-8');
    const files = JSON.parse(metadataContent);

    // Return files (without the full path for security)
    const filesList = files.map((file: any) => ({
      id: file.id,
      name: file.originalName,
      type: file.type.toLowerCase(),
      size: file.size,
      uploadedAt: file.uploadedAt,
      path: `/api/files/${file.id}/content`,
    }));

    return NextResponse.json({ files: filesList });
  } catch (error) {
    console.error('Error reading files:', error);
    return NextResponse.json(
      { error: 'Failed to fetch files', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 }
    );
  }
}

async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // Await params to get the actual values
    const { id: fileId } = await params;

    if (!fileId) {
      return NextResponse.json(
        { error: 'File ID is required' },
        { status: 400 }
      );
    }

    // Check if metadata file exists
    if (!existsSync(METADATA_FILE)) {
      return NextResponse.json(
        { error: 'No files found' },
        { status: 404 }
      );
    }

    // Read metadata file
    const metadataContent = await readFile(METADATA_FILE, 'utf-8');
    const files = JSON.parse(metadataContent);

    // Find the file to delete
    const fileIndex = files.findIndex((file: any) => file.id === fileId);

    if (fileIndex === -1) {
      return NextResponse.json(
        { error: 'File not found' },
        { status: 404 }
      );
    }

    const fileToDelete = files[fileIndex];

    // Delete the physical file
    const filePath = fileToDelete.path || path.join(UPLOAD_DIR, fileToDelete.fileName);
    if (existsSync(filePath)) {
      try {
        await unlink(filePath);
      } catch (error) {
        console.error('Error deleting file:', error);
        // Continue even if file deletion fails (file might not exist)
      }
    }

    // Remove file from metadata
    files.splice(fileIndex, 1);

    // Save updated metadata
    await writeFile(METADATA_FILE, JSON.stringify(files, null, 2), 'utf-8');

    return NextResponse.json({
      success: true,
      message: 'File deleted successfully',
    });
  } catch (error) {
    console.error('Delete error:', error);
    return NextResponse.json(
      { error: 'Failed to delete file', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 }
    );
  }
}

async function GET(
    request: NextRequest,
    { params }: { params: Promise<{ id: string }> }
) {
    try {
        const { id } = await params;

        if (!id) {
            return NextResponse.json({ error: 'File ID is required' }, { status: 400 });
        }

        // Read metadata to find the file
        if (!existsSync(METADATA_FILE)) {
            return NextResponse.json({ error: 'File not found' }, { status: 404 });
        }

        const metadataContent = await readFile(METADATA_FILE, 'utf-8');
        const files = JSON.parse(metadataContent);
        const file = files.find((f: any) => f.id === id);

        if (!file) {
            return NextResponse.json({ error: 'File not found' }, { status: 404 });
        }

        // Construct file path
        const filePath = file.path || path.join(UPLOAD_DIR, file.fileName);

        if (!existsSync(filePath)) {
            return NextResponse.json({ error: 'File not found on disk' }, { status: 404 });
        }

        // Read and serve the file
        const fileBuffer = await readFile(filePath);
        const fileExtension = path.extname(file.fileName).toLowerCase();

        // Set appropriate content type
        const contentTypeMap: Record<string, string> = {
            '.pdf': 'application/pdf',
            '.md': 'text/markdown',
            '.txt': 'text/plain',
        };

        const contentType = contentTypeMap[fileExtension] || 'application/octet-stream';

        // Header values must be ASCII (ByteString). Strip non-ASCII to avoid "character at index N has a value of 55357" error.
        const safeFilename = (file.originalName || file.fileName || 'document')
            .replace(/[^\x00-\x7F]+/g, '_')
            .replace(/"/g, "'");

        return new NextResponse(fileBuffer, {
            headers: {
                'Content-Type': contentType,
                'Content-Disposition': `inline; filename="${safeFilename}"`,
            },
        });

    } catch (error) {
        console.error('Error serving file:', error);
        return NextResponse.json(
            { error: 'Failed to serve file', details: error instanceof Error ? error.message : 'Unknown error' },
            { status: 500 }
        );
    }
}

async function ensureDirectories() {
  if (!existsSync(UPLOAD_DIR)) {
    await mkdir(UPLOAD_DIR, { recursive: true });
  }
  const dataDir = path.join(process.cwd(), 'data');
  if (!existsSync(dataDir)) {
    await mkdir(dataDir, { recursive: true });
  }
  // Initialize metadata file if it doesn't exist
  if (!existsSync(METADATA_FILE)) {
    await writeFile(METADATA_FILE, JSON.stringify([]), 'utf-8');
  }
}

async function POST(request: NextRequest) {
  try {
    await ensureDirectories();

    const formData = await request.formData();
    const files = formData.getAll('files') as File[];

    if (!files || files.length === 0) {
      return NextResponse.json(
        { error: 'No files provided' },
        { status: 400 }
      );
    }

    const uploadedFiles = [];
    const allowedTypes = ['.pdf', '.md', '.txt', '.csv'];
    const maxSize = 20 * 1024 * 1024; // 20MB

    // Read existing metadata
    let fileMetadata: any[] = [];
    try {
      const metadataContent = await readFile(METADATA_FILE, 'utf-8');
      fileMetadata = JSON.parse(metadataContent);
    } catch (error) {
      fileMetadata = [];
    }

    for (const file of files) {
      // Validate file type
      const fileExtension = '.' + file.name.split('.').pop()?.toLowerCase();
      if (!allowedTypes.includes(fileExtension)) {
        continue; // Skip invalid files
      }

      // Validate file size
      if (file.size > maxSize) {
        continue; // Skip oversized files
      }

      // Generate unique filename to avoid conflicts
      const timestamp = Date.now();
      const randomStr = Math.random().toString(36).substring(2, 9);
      const sanitizedName = file.name.replace(/[^a-zA-Z0-9.-]/g, '_');
      const uniqueFileName = `${timestamp}_${randomStr}_${sanitizedName}`;
      const filePath = path.join(UPLOAD_DIR, uniqueFileName);

      // Convert file to buffer and save
      const bytes = await file.arrayBuffer();
      const buffer = Buffer.from(bytes);
      await writeFile(filePath, buffer);

      // Create metadata entry
      const metadata = {
        id: `${timestamp}_${randomStr}`,
        originalName: file.name,
        fileName: uniqueFileName,
        type: fileExtension.substring(1).toUpperCase(),
        size: file.size,
        uploadedAt: new Date().toISOString(),
        path: filePath,
      };

      fileMetadata.push(metadata);
      uploadedFiles.push(metadata);
    }

    // Save updated metadata
    await writeFile(METADATA_FILE, JSON.stringify(fileMetadata, null, 2), 'utf-8');

    return NextResponse.json({
      success: true,
      message: `Successfully uploaded ${uploadedFiles.length} file(s)`,
      files: uploadedFiles,
    });
  } catch (error) {
    console.error('Upload error:', error);
    return NextResponse.json(
      { error: 'Failed to upload files', details: error instanceof Error ? error.message : 'Unknown error' },
      { status: 500 }
    );
  }
}

